class Solution {
public:
    int getIndex(ArrayReader& reader) {
        int left = 0;
        int right = reader.length() - 1;
        while (left < right) {
            int length = right - left + 1;
            int half = length / 2;
            int leftEnd = left + half - 1;
            int rightStart = right - half + 1;
            int result = reader.compareSub(left, leftEnd, rightStart, right);
            if (result > 0) {
                right = leftEnd;
            } else if (result < 0) {
                left = rightStart;
            } else {
                return left + half;
            }
        }
        return left;
    }
};
